import sys
import math

MOD = 1000000007

def add_modulo(x, y):
    x += y
    if x >= MOD:
        x -= MOD
    return x

def mul_modulo(x, y):
    res = (x * y) % MOD
    return res

def sub_modulo(x, y):
    x -= y
    if x < 0:
        x += MOD
    return x

def pow_modulo(base, exp):
    res = 1
    while exp > 0:
        if exp & 1:
            res = mul_modulo(res, base)
        base = mul_modulo(base, base)
        exp >>= 1
    return res

def get_lowbit(x):
    return x & (-x)

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = [[0]*n for _ in range(n)]
    index = 1
    for i in range(n):
        for j in range(n):
            a[i][j] = int(data[index])
            index += 1
    inv_100 = pow_modulo(100, MOD - 2)
    for i in range(n):
        for j in range(n):
            a[i][j] = mul_modulo(a[i][j], inv_100)
    # Initialize data structures
    id_count = 0
    ch = {}
    q = [[0]*(1<<n) for _ in range(n)]
    dp = [[0]*(70010) for _ in range(n+1)]
    id_map = {}
    # DFS function
    def dfs(s):
        s_tuple = tuple(s)
        if s_tuple in id_map:
            return id_map[s_tuple]
        nonlocal id_count
        id_count += 1
        id_map[s_tuple] = id_count
        ch[id_count] = [0]*(1<<n)
        for i in range(1<<n):
            tmp = s[:]
            for j in range(1<<n):
                if not tmp[j]:
                    x = i & j
                    while x:
                        t = get_lowbit(x)
                        if s[j ^ (t.bit_length() - 1)]:
                            tmp[j] = 1
                            break
                        x -= t
            ch[id_count][i] = dfs(tmp)
        return id_count

    # Initialize the starting bitset
    s_start = [0]* (1<<n)
    s_start[0] = 1
    dfs(s_start)

    # Precompute q
    for i in range(n):
        for j in range(1<<n):
            q[i][j] = 1
            for k in range(n):
                if (j >> k) & 1:
                    q[i][j] = mul_modulo(q[i][j], a[i][k])
                else:
                    q[i][j] = mul_modulo(q[i][j], sub_modulo(1, a[i][k]))

    # Initialize DP
    dp[0][1] = 1
    for i in range(1, n+1):
        for j in range(1, id_count+1):
            for k in range(1<<n):
                dp[i][ch[j][k]] = add_modulo(dp[i][ch[j][k]], mul_modulo(dp[i-1][j], q[i-1][k]))

    # Final bitset
    bits = [1]* (1<<n)
    print(dp[n][id_map[tuple(bits)]])

main()

